def as1_obstacle_monitor(scan, sstate, t, P):
    st = dict(sstate) if sstate else {}
    near = False
    if scan is not None:
        lim = math.radians(P['safe_sector_deg'])
        for i, r in enumerate(scan.ranges):
            if not math.isfinite(r) or r >= P['safe_dist']:
                continue
            if abs(wrap(scan.angle_min + i * scan.angle_increment)) <= lim:
                near = True
                break
    if near:
        st['last_near'] = t
    clear = (not near) and (t - st.get('last_near', -1e18)) >= P['clear_s']
    return st, near, clear


def as2_inhibit_forward(cmd):
    return Command(min(cmd.v, 0.0), cmd.w)
